Object.assign(I18N.DICT.it.T, {"rq": ["Squalo", "Nuota in linea retta (su, giù, sinistra, destra) fino a 3 caselle; cattura arrivando su un nemico."], "mz": ["Medusa", "Fa 1 passo in diagonale, oppure punge senza muoversi un nemico attaccato a lei in linea retta (su, giù, sinistra, destra)."], "pv": ["Polpo", "I suoi tentacoli afferrano un nemico a 2 o 3 caselle (nelle 8 direzioni, sopra tutto) e lo riportano attaccato a sé. Non dei né boss."], "sr": ["Sirena", "Il suo canto respinge di una casella tutti i nemici attaccati a lei; quelli spinti fuori dalla mappa o in un buco muoiono."], "bl": ["Leviatano", "Boss, 4 punti vita. Un turno su due si immerge (non si può colpire) e segna in rosso la casella della tua guardia o del tuo soldato più prezioso; al turno successivo riemerge sotto di lui e lo divora."], "bm": ["Signore delle maree", "Boss, 4 punti vita. Un turno su due, la marea respinge tutte le tue unità di una casella verso il tuo campo."], "bo": ["Grande Corallo", "Boss, 5 punti vita. Alla fine di ogni turno della sua parte cresce corallo (una casella bloccata) accanto a lui o al suo corallo, verso di te (al massimo 6). Ogni 3 turni recupera 1 punto vita."], "bj": ["Medusa gigante", "Boss, 3 punti vita. Un turno su due, un fulmine colpisce la tua unità più vicina a lei (a 3 caselle o meno) e poi salta su una tua unità attaccata a quella."], "bx": ["Dio caduto", "Boss finale, in 2 fasi. Prima (3 punti vita) chiama un tirapiedi a ogni turno e schiaccia un’unità attaccata a lui un turno su due. Poi si rialza (4 punti vita): avanza verso di te e sputa fuoco in linea un turno su due."], "om": ["Madre delle ombre", "Fa uscire un’Ombra (un soldato delle ombre dalla riserva comune) su una casella vuota accanto a una delle tue unità."], "of": ["Mietitore", "Uccide un nemico (non un dio) accanto a una delle tue unità."], "oe": ["Eclissi", "Fa piombare la mappa nel buio: nel suo prossimo turno l’avversario non può né schierare né attivare unità."], "ou": ["Divoratore di anime", "Sacrifica una delle tue unità attaccate a lui (non un dio): guadagni 50 mana."], "oa": ["Assassino", "Fa 1 passo su una casella vuota, oppure balza di 2 caselle (in linea retta o in diagonale, sopra tutto); cattura arrivando su un nemico."], "ob": ["Bruma", "Si teletrasporta su una casella vuota a 3 caselle o meno, o su un nemico a 2 caselle o meno per catturarlo."], "oc": ["Corvo", "Vola in diagonale fino a 3 caselle sopra tutto; cattura arrivando su un nemico."], "ol": ["Lama", "Avanza di 2 caselle in linea retta (su, giù, sinistra, destra) e uccide i nemici che attraversa."], "ox": ["Pipistrello", "Vola di 2 caselle (in linea retta o in diagonale) sopra tutto; cattura arrivando su un nemico."], "os": ["Ombra", "Soldato delle ombre: fa 1 passo dritto (anche all’indietro) su una casella vuota; cattura in diagonale in avanti."], "bv": ["Cuore di lava", "Boss, 4 punti vita. Un turno su due segna in rosso la casella della tua guardia o del tuo soldato più prezioso; al turno successivo lì sgorga la lava: se è ancora sopra, muore."]});
I18N.DICT.it.SPEC[3] = ["Corrente", "Alla fine del tuo turno, ogni tua unità su una corrente viene trascinata di una casella nel senso della freccia (se la casella è libera)."];
I18N.DICT.it.THEME.abysses = ["Abissi"];
// équilibrage du 2026-10-22 : nouvelles descriptions
I18N.DICT.it.T.g5[1] = "3 volte di fila: un passo dritto (su, giù, sinistra, destra) su una casella vuota, o una presa in diagonale.";
I18N.DICT.it.T.g6[1] = "Può prima fare 1 o 2 passi, poi colpisce tutte le caselle intorno a sé: muoiono tutti i nemici attaccati.";
I18N.DICT.it.T.g7[1] = "Fa fino a 3 passi in diagonale (può catturare a ogni passo).";
I18N.DICT.it.T.c4[1] = "Tira in diagonale: uccide il 1° nemico della diagonale senza muoversi. Oppure fa 1 passo dritto su una casella vuota.";
I18N.DICT.it.T.c5[1] = "Atterra su qualsiasi casella a più di 5 caselle (righe + colonne); lì può catturare un soldato, ma né una guardia né un dio.";
I18N.DICT.it.T.c6[1] = "Trasforma uno dei tuoi soldati attaccati a lui in 40 mana (il soldato sparisce) e rigiochi subito. Altrimenti ti fa guadagnare 15 mana.";
I18N.DICT.it.T.c7[1] = "Tira in linea retta senza muoversi: uccide il 1° nemico della linea e trapassa fino al successivo. Oppure fa 1 passo in diagonale su una casella vuota.";
I18N.DICT.it.T.lc[1] = "Colpisce le 3 caselle davanti a sé in linea retta (su, giù, sinistra o destra), senza muoversi. Se in quella direzione non c’è nessun nemico, avanza di un passo.";
I18N.DICT.it.T.gd[1] = "Fa 1 o 2 passi in qualsiasi direzione (come il re degli scacchi, due volte); cattura arrivando su un nemico.";
I18N.DICT.it.T.mz[1] = "Fa 1 passo in qualsiasi direzione, oppure punge senza muoversi un nemico attaccato a lei (nelle 8 direzioni).";
I18N.DICT.it.T.rq[1] = "Nuota in linea retta (su, giù, sinistra, destra) fino a 4 caselle; cattura arrivando su un nemico.";
I18N.DICT.it.THEME.nuit = ["Foresta di notte"];
I18N.DICT.it.T.c5[1] = "Atterra su qualsiasi casella a più di 5 caselle (righe + colonne); lì può catturare un soldato, o una guardia a più di 6 caselle, mai un dio.";
I18N.DICT.it.T.mz[1] = "Fa 1 passo in qualsiasi direzione su una casella vuota, oppure punge senza muoversi tutti i nemici attaccati a lei in linea retta (su, giù, sinistra, destra).";
I18N.DICT.it.T.g4[1] = "Avanza di 1 casella in 8 direzioni spingendo tutta la fila davanti a sé (un’unità spinta fuori dalla mappa o in un buco muore), poi può fare un 2° passo su una casella vuota o su un nemico per catturarlo.";
I18N.DICT.it.T.mz[1] = "Fa 1 passo in qualsiasi direzione su una casella vuota, oppure punge senza muoversi un nemico a 1 o 2 caselle in linea retta (su, giù, sinistra, destra), anche sopra un’unità.";
I18N.DICT.it.T.c5[1] = "Atterra su qualsiasi casella a più di 5 caselle (righe + colonne); lì può catturare un soldato, o una guardia a più di 7 caselle, mai un dio.";
I18N.DICT.it.T.g4[1] = "Avanza di 1 casella in 8 direzioni spingendo tutta la fila davanti a sé (un’unità spinta fuori dalla mappa o in un buco muore), poi può fare un 2° passo su una casella vuota o su un nemico (non un dio) per catturarlo.";
I18N.DICT.it.T.g1[1] = "Scambia il posto con qualsiasi unità della mappa (alleata o avversaria, persino un dio). Se sceglie un nemico attaccato a lui, lo cattura invece di scambiarsi.";
// DLC « Les Ombres » : boss de la Lumière et nouvelles cases
Object.assign(I18N.DICT.it.T, {"sa": ["Arcangelo", "Boss della Luce, 4 punti vita. Un turno su due, la sua luce acceca tutte le tue unità sulla sua riga e colonna: non puoi attivarle al tuo turno successivo."], "sp": ["Paladino", "Boss della Luce, 3 punti vita. Finché 2 delle sue unità sono attaccate a lui, lo proteggono: i tuoi colpi non gli fanno nulla. Uccidi prima le sue guardie! Avanza verso di te un turno su due (lasciando a volte indietro le sue guardie) e colpisce un’unità attaccata a lui ogni 4 turni."], "sl": ["Faro", "Boss della Luce, 2 punti vita. Non si muove, ma la sua luce blocca le tue guardie e i tuoi soldati: quelli a 2 caselle o meno non possono essere attivati (i tuoi dei sì). Colpiscilo da lontano! Ogni 4 turni chiama un servitore."], "sg": ["Golem di cristallo", "Boss della Luce, 2 punti vita. Il suo cristallo respinge tiri e incantesimi: solo i colpi in mischia lo feriscono. Ogni 4 turni schiaccia un’unità attaccata a lui."]});
I18N.DICT.it.SPEC[4] = ["Altare delle ombre", "All’inizio del tuo turno, se una delle tue unità delle Ombre è sopra: +20 mana."];
I18N.DICT.it.SPEC[5] = ["Luce sacra", "Un’unità delle Ombre (non un dio) ancora sopra alla fine del turno del suo schieramento muore."];
I18N.DICT.it.SPEC[6] = ["Portale", "Alla fine del tuo turno, la tua unità su un portale passa dal portale gemello (dall’altra parte della mappa), se è libero."];
// armée des Ombres complète : noms des jumeaux
Object.assign(I18N.DICT.it.T, {"na": ["Tempesta nera"], "nb": ["Specchio oscuro"], "nc": ["Manipolatore"], "nd": ["Capobranco"], "ne": ["Battitore"], "nf": ["Clessidra nera"], "ng": ["Voragine"], "nh": ["Corno delle ombre", "Una delle tue Ombre (soldato delle ombre) fa 2 passi di fila."], "ni": ["Evocatore", "Recluta un’Ombra (soldato delle ombre) e la piazza subito nella tua zona di schieramento."], "nj": ["Catene"], "nk": ["Vendetta"], "n1": ["Sosia"], "n2": ["Torre nera"], "n3": ["Arciera oscura"], "n4": ["Mastodonte"], "n5": ["Predone"], "n6": ["Tormento"], "n7": ["Fuoco fatuo"], "n8": ["Gargoyle"], "n9": ["Sacerdote oscuro"], "nl": ["Balestra d’osso"], "nm": ["Catapulta d’osso"], "nn": ["Cavaliere senza testa"], "no": ["Sentinella"]});
// armée des Ombres : pouvoirs à elle
Object.assign(I18N.DICT.it.T, {"na": ["Possessione", "Prende il controllo di un soldato o di una guardia nemica attaccata a una tua unità: passa dalla tua parte (conta come persa per l’avversario)."], "nb": ["Maledizione", "Maledice un nemico (non un dio) ovunque sulla mappa: se è ancora sulla stessa casella alla fine del prossimo turno del suo schieramento, muore."], "nc": ["Passaggio", "Fa passare una tua unità (non un dio) attraverso le ombre: riappare su una casella vuota attaccata a un’altra tua unità."], "nd": ["Ladro di anime", "Ruba fino a 30 mana all’avversario."], "ne": ["Ululato", "Tutti i nemici (non gli dei) nella tua metà della mappa arretrano di una casella verso il loro lato, se la casella è libera."], "nf": ["Richiamo dei morti", "Fa entrare 2 Ombre (soldati delle ombre) nella tua riserva, più 1 per ogni guardia che hai perso (al massimo 4)."], "ng": ["Catena", "Incatena un’unità nemica (anche un dio): non può essere attivata nei 2 prossimi turni del suo schieramento."], "nh": ["Porta delle ombre", "Apre una porta: una tua guardia o un tuo soldato riappare su una casella vuota della zona di schieramento avversaria."], "ni": ["Piaga", "Muoiono tutti i soldati nemici attaccati ad almeno 2 tue unità."], "nj": ["Sudario", "Copre una tua unità e le tue unità attaccate a lei: niente può ucciderle fino al tuo prossimo turno."], "nk": ["Marea nera", "Tutte le tue Ombre (soldati delle ombre) avanzano di una casella verso l’avversario, se la casella è libera."], "n1": ["Fantasma", "Attraversa tutto: si posa su una casella vuota a 3 caselle o meno. Dove arriva, i soldati nemici attaccati muoiono di paura e le guardie nemiche attaccate non possono essere attivate al loro prossimo turno."], "n2": ["Ghoul", "Fa 1 passo in qualsiasi direzione; cattura arrivando su un nemico. Dopo una cattura può fare un altro passo (al massimo 3)."], "n3": ["Vampiro", "Fa 1 passo su una casella vuota (8 direzioni), oppure morde senza muoversi un nemico a 1 o 2 caselle in linea retta o in diagonale, sopra tutto (non un dio): il nemico muore e guadagni 20 mana."], "n4": ["Ragno", "Fa 1 passo dritto su una casella vuota, oppure lancia la ragnatela sulla 1ª unità nemica in linea retta a 4 caselle o meno: un soldato muore, una guardia o un dio non può essere attivato per 2 turni del suo schieramento."], "n5": ["Poltergeist", "Fa 1 passo dritto su una casella vuota, oppure afferra un nemico a 1 o 2 caselle in linea retta o in diagonale (non un dio) e lo scaglia 2 caselle più in là: se cade fuori dalla mappa, in un buco o su un’unità, muore."], "n6": ["Serpente", "Striscia fino a 3 passi dritti (su, giù, sinistra, destra), girando come vuole, su caselle vuote; cattura arrivando su un nemico."], "n7": ["Lupo mannaro", "Fa 1 passo in qualsiasi direzione (cattura arrivando su un nemico). Se è attaccato a 2 nemici o più, può andare su tutte le furie: muoiono tutti i nemici attaccati a lui (non gli dei)."], "n8": ["Larva", "Fa 1 passo dritto su una casella vuota, o cattura in diagonale. Quando muore, 2 Ombre nascono intorno a lei."], "n9": ["Demone", "Fa 1 passo in qualsiasi direzione (cattura arrivando su un nemico), oppure sbuca su una casella vuota attaccata a un dio nemico."], "nl": ["Scheletro", "Fa 1 passo dritto (cattura arrivando su un nemico), oppure lancia un osso senza muoversi a un nemico a 2 o 3 caselle in linea retta (non un dio). Quando muore, si rialza come Ombra subito accanto."], "nm": ["Riflesso", "Fa 1 passo dritto su una casella vuota, oppure salta nel suo riflesso: la casella simmetrica sulla stessa riga, dall’altra parte (sinistra ↔ destra); lì cattura un nemico, non un dio."], "nn": ["Boia", "Fa 1 passo su una casella vuota (8 direzioni), oppure giustizia senza muoversi un nemico attaccato a lui (non un dio) che è attaccato anche a un’altra tua unità."], "no": ["Strisciante", "Striscia dritto verso l’avversario, fino a 4 caselle, su caselle vuote; cattura arrivando su un nemico."]});
I18N.DICT.it.T.oa[1] = "Fa 1 passo su una casella vuota, oppure balza a 2 o 3 caselle (in linea retta o in diagonale, sopra tutto); cattura arrivando su un nemico.";
I18N.DICT.it.T.oc[1] = "Vola in diagonale fino a 4 caselle sopra tutto; cattura arrivando su un nemico.";
